ON CONFLICT (slug) DO UPDATE SET
name = EXCLUDED.name, icon = EXCLUDED.icon, gradient = EXCLUDED.gradient;

-- Note: In a real migration you would get the category_id from the categories table and insert them, 
-- but for simplicity we will insert the products without category_id for now, 
-- or you can manually assign them in the Admin Panel.

ON CONFLICT (slug) DO UPDATE SET
title = EXCLUDED.title, "desc" = EXCLUDED."desc", icon = EXCLUDED.icon, gradient = EXCLUDED.gradient, specs = EXCLUDED.specs, featured = EXCLUDED.featured, status = EXCLUDED.status, images = EXCLUDED.images;
